FA = [da0, da1, da2, da3, da4, da5, da6, da7, da8, da9, da10, da11, da12, da13, da14, da15, da16, da17, da18, da19, da20, da21, da22, da23, da24, da25, da26, da27, da28, da29, da30, da31]


FB = [db0, db1, db2, db3, db4, db5, db6, db7, db8, db9, db10, db11, db12, db13, db14, db15, db16, db17, db18, db19, db20, db21, db22, db23, db24, db25, db26, db27, db28, db29, db30, db31]


NA = 725



def wait_until(e):
	while get_time() < e:
		pass


def travel(x, y):
	dx = x - get_pos_x()
	if dx < 0:
		dx += N
	if dx <= N // 2:
		for _ in range(dx):
			move(East)
	else:
		for _ in range(N - dx):
			move(West)
	dy = y - get_pos_y()
	if dy < 0:
		dy += N
	if dy <= N // 2:
		for _ in range(dy):
			move(North)
	else:
		for _ in range(N - dy):
			move(South)


def walk(cx, cy, x, y):
	if x > cx:
		for _ in range(x - cx):
			move(East)
	else:
		for _ in range(cx - x):
			move(West)
	if y > cy:
		for _ in range(y - cy):
			move(North)
	else:
		for _ in range(cy - y):
			move(South)


# d = [xs, ys, nb, ext, mv, pj, pd, pu]: cells in the order this pass plants them; nb[i] = flat
# (index, direction, 1 if that neighbour is above) triples for every neighbour in the chunk; ext =
# [direction, above] of the pair across the cut at the last cell, or []; mv[i] = direction from the
# cell before, or -1; pj[i] = index of the one earlier neighbour to compare with (pd, pu its
# direction and side), -2 for none, -1 when the cell needs the full repair.
def run(c, d, fresh, left, guard):
	xs = d[0]
	ys = d[1]
	nb = d[2]
	mv = d[4]
	pj = d[5]
	pd = d[6]
	pu = d[7]
	n = len(xs)
	vals = []
	for _ in range(n):
		vals.append(None)
	cx = get_pos_x()
	cy = get_pos_y()
	away = True
	for i in range(n):
		x = xs[i]
		y = ys[i]
		m = mv[i]
		if away or m < 0:
			walk(cx, cy, x, y)
			away = False
		else:
			move(DIRS[m])
		cx = x
		cy = y
		if fresh:
			till()
		elif left:
			if get_entity_type() != None:
				harvest()
		plant(Entities.Cactus)
		va = measure()
		vals[i] = va
		j = pj[i]
		if j >= 0:
			vj = vals[j]
			if pu[i] == 1:
				if va > vj:
					swap(DIRS[pd[i]])
					vals[i] = vj
					vals[j] = va
			elif va < vj:
				swap(DIRS[pd[i]])
				vals[i] = vj
				vals[j] = va
		elif j == -1:
			work = [i]
			while len(work) > 0:
				a = work.pop()
				e = nb[a]
				m = len(e)
				k = 0
				while k < m:
					j = e[k]
					vj = vals[j]
					if vj != None:
						va = vals[a]
						if e[k + 2] == 1:
							bad = va > vj
						else:
							bad = va < vj
						if bad:
							ax = xs[a]
							ay = ys[a]
							bx = xs[j]
							by = ys[j]
							if abs(ax - cx) + abs(ay - cy) <= abs(bx - cx) + abs(by - cy):
								walk(cx, cy, ax, ay)
								cx = ax
								cy = ay
								swap(DIRS[e[k + 1]])
							else:
								walk(cx, cy, bx, by)
								cx = bx
								cy = by
								swap(DIRS[(e[k + 1] + 2) % 4])
							vals[a] = vj
							vals[j] = va
							work.append(j)
							work.append(a)
							k = m
					k += 3
			away = cx != x or cy != y
	ex = d[3]
	if len(ex) > 0:
		i = n - 1
		walk(cx, cy, xs[i], ys[i])
		wait_until(guard)
		w = DIRS[ex[0]]
		v = measure(w)
		while v == None:
			v = measure(w)
		h = measure()
		if ex[1] == 1:
			if h > v:
				swap(w)
		elif h < v:
			swap(w)


def worker(c):
	da = FA[c]()
	db = FB[c]()
	travel(da[0][0], da[1][0])
	forward = True
	fresh = True
	left = False
	pump = PUMP0
	last = 0
	guard = GUARD_A
	while True:
		if forward:
			run(c, da, fresh, left, guard)
			travel(db[0][0], db[1][0])
		else:
			run(c, db, fresh, left, guard)
			travel(da[0][0], da[1][0])
		pump -= SEED_COST * NA
		if c == 0:
			while num_items(Items.Pumpkin) > pump:
				pass
			wait_until(get_time() + GROW)
			harvest()
		while num_items(Items.Cactus) <= last:
			pass
		got = num_items(Items.Cactus)
		left = got - last < FULL
		last = got
		guard = get_time() + GUARD_B
		if last >= GOAL:
			return
		forward = not forward
		fresh = False


def launch(xs):
	while len(xs) > 1:
		half = len(xs) // 2
		keep = []
		rest = []
		for k in range(len(xs)):
			if k < half:
				keep.append(xs[k])
			else:
				rest.append(xs[k])
		spawn_drone(launch, rest)
		xs = keep
	worker(xs[0])


FULL = 32 * NA * NA
PUMP0 = num_items(Items.Pumpkin)
CS = []
for ci in range(len(FA)):
	CS.append(ci)
launch(CS)
